// Executes actions returned by orch(); follow-up events go back to orch.
const token = $env.TELEGRAM_BOT_TOKEN;
const chat = $env.TELEGRAM_CHAT_ID;
const next = [];
for (const item of $input.all()) {
  for (const a of item.json.actions || []) {
    if (a.type === 'run') {
      try {
        await this.helpers.httpRequest({ method: 'POST', url: a.url, body: a.command, json: true, timeout: 15000 });
      } catch (e) {
        next.push({ json: { event: { type: 'dispatch_failed', run_id: a.command.run_id, role: a.command.role, error: String(e.message || e).slice(0, 500) } } });
      }
    } else if (a.type === 'telegram') {
      const body = { chat_id: chat, text: a.text, disable_web_page_preview: true };
      if (a.buttons) body.reply_markup = { inline_keyboard: a.buttons };
      try {
        const r = await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/sendMessage`, body, json: true, timeout: 15000 });
        if (a.approval_id) next.push({ json: { event: { type: 'message', approval_id: a.approval_id, message_id: r.result.message_id } } });
      } catch (e) {
        console.log('telegram send failed', String(e.message || e));
      }
    }
  }
}
return next;
